    ($SATQ$68c5c81a$SATQ$, $SATQ$4ab12ef2-53a0-47fe-ac2b-2bb21f21eb96$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Algebra$SATQ$, $SATQ$H$SATQ$, $SATQ$H.E.$SATQ$, $SATQ$Linear inequalities in one or two variables$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: center;"><math alttext="11 x plus 14 y less than or equals 115"><mn>11</mn><mi>x</mi><mo>+</mo><mn>14</mn><mi>y</mi><mo>&#8804;</mo><mn>115</mn></math></p>
<p style="text-align: left;">Anthony will spend at most <math alttext="dollar sign 115"><mo>$</mo><mn>115</mn></math> to purchase <math alttext="x"><mi>x</mi>
</math> small cheese pizzas and <math alttext="y"><mi>y</mi>
</math> large cheese pizzas for a team dinner. The given inequality represents this situation. Which of the following is the best interpretation of <math alttext="14 y"><mrow>
	<mn>14</mn>
	<mi>y</mi>
</mrow>
</math> in this context?</p>$SATQ$, $SATQ$[{"id":"8a5f98dc-cda2-4168-bef0-b0abf6dfb737","content":"<p style=\"text-align: left;\">The amount, in dollars, Anthony will spend on each large cheese pizza</p>"},{"id":"773e4e8e-a041-425d-9c26-38752fe563e3","content":"<p style=\"text-align: left;\">The amount, in dollars, Anthony will spend on each small cheese pizza</p>"},{"id":"66ae8993-e3f9-4ec5-843f-c17baf5541d5","content":"<p style=\"text-align: left;\">The total amount, in dollars, Anthony will spend on large cheese pizzas</p>"},{"id":"9640a8f7-bd79-41c1-9226-1a6f798b1d1e","content":"<p style=\"text-align: left;\">The total amount, in dollars, Anthony will spend on small cheese pizzas</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["66ae8993-e3f9-4ec5-843f-c17baf5541d5"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">Choice C is correct. It's given that Anthony will spend at most <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="dollar sign 115"><mo>$</mo><mn>115</mn></math> to purchase <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x"><mi>x</mi></math> small cheese pizzas and <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="y"><mi>y</mi></math> large cheese pizzas. In the inequality <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="11 x plus 14 y less than or equals 115"><mn>11</mn><mi>x</mi><mo>+</mo><mn>14</mn><mi>y</mi><mo>≤</mo><mn>115</mn></math><span style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;">, <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="y"><mi>y</mi></math> represents the number of large cheese pizzas that Anthony will purchase. This means the coefficient <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="14"><mn>14</mn></math> represents the amount, in dollars, Anthony will spend on each large cheese pizza. Therefore, the best interpretation of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="14 y"><mn>14</mn><mi>y</mi></math> in this context is the total amount, in dollars, Anthony will spend on large cheese pizzas.</span></p>
<p style="text-align: left;">Choice A is incorrect. This is the best interpretation of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="14"><mn>14</mn></math>, not <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="14 y"><mn>14</mn><mi>y</mi></math>.</p>
<p style="text-align: left;">Choice B is incorrect. This is the best interpretation of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="11"><mn>11</mn></math>, not <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="14 y"><mn>14</mn><mi>y</mi></math>.</p>
<p style="text-align: left;">Choice D is incorrect. This is the best interpretation of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="11 x"><mn>11</mn><mi>x</mi></math>, not <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="14 y"><mn>14</mn><mi>y</mi></math>.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"68c5c81a","external_id":"4ab12ef2-53a0-47fe-ac2b-2bb21f21eb96","disclosed_item_id":null,"source":"qbank","vaultid":null,"uId":"ba8c10d8-37f6-487e-bb9d-f1f1505e5e48","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"H","domain":"Algebra","skill_cd":"H.E.","skill_desc":"Linear inequalities in one or two variables","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":null,"stem":"<p style=\"text-align: center;\"><math alttext=\"11 x plus 14 y less than or equals 115\"><mn>11</mn><mi>x</mi><mo>+</mo><mn>14</mn><mi>y</mi><mo>&#8804;</mo><mn>115</mn></math></p>\n<p style=\"text-align: left;\">Anthony will spend at most <math alttext=\"dollar sign 115\"><mo>$</mo><mn>115</mn></math> to purchase <math alttext=\"x\"><mi>x</mi>\n</math> small cheese pizzas and <math alttext=\"y\"><mi>y</mi>\n</math> large cheese pizzas for a team dinner. The given inequality represents this situation. Which of the following is the best interpretation of <math alttext=\"14 y\"><mrow>\n\t<mn>14</mn>\n\t<mi>y</mi>\n</mrow>\n</math> in this context?</p>","answerOptions":[{"id":"8a5f98dc-cda2-4168-bef0-b0abf6dfb737","content":"<p style=\"text-align: left;\">The amount, in dollars, Anthony will spend on each large cheese pizza</p>"},{"id":"773e4e8e-a041-425d-9c26-38752fe563e3","content":"<p style=\"text-align: left;\">The amount, in dollars, Anthony will spend on each small cheese pizza</p>"},{"id":"66ae8993-e3f9-4ec5-843f-c17baf5541d5","content":"<p style=\"text-align: left;\">The total amount, in dollars, Anthony will spend on large cheese pizzas</p>"},{"id":"9640a8f7-bd79-41c1-9226-1a6f798b1d1e","c